var ENT=[["Indexer", "Signature Indexer pillar of the Metadata Filter Engine framework."], ["Ranker", "Signature Ranker pillar of the Metadata Filter Engine framework."], ["Tokenizer", "Signature Tokenizer pillar of the Metadata Filter Engine framework."], ["Facetor", "Signature Facetor pillar of the Metadata Filter Engine framework."], ["Typo Tamer", "Signature Typo Tamer pillar of the Metadata Filter Engine framework."], ["Vector Seeker", "Signature Vector Seeker pillar of the Metadata Filter Engine framework."], ["Hybridizer", "Signature Hybridizer pillar of the Metadata Filter Engine framework."]];
var TECH=[["Inverted indexing", "Mapping each term to the documents containing it for O(1) term lookup."], ["TF-IDF weighting", "Term frequency times inverse document frequency scoring distinctive terms higher."], ["Tokenization and stemming", "Splitting text and reducing words to roots before indexing."], ["Faceted search", "Aggregating result counts by category, brand or price for guided navigation."], ["Typo tolerance", "Edit-distance matching so misspelled queries still find results."], ["Vector similarity search", "Ranking by embedding cosine distance for semantic rather than keyword match."], ["Hybrid retrieval", "Fusing keyword BM25 scores with vector scores for the best of both."], ["Query expansion", "Adding synonyms or related terms to bridge vocabulary gaps."], ["Result highlighting", "Snippeting matched passages so users see why a hit ranked."], ["Relevance tuning", "A/B testing ranking functions against click and conversion signals."]];
